// The two big diagrams that looked sloppy (homelab and AWS reference architecture), as layout inputs.
// Sizes follow what build_diagram computes: icon node = 52 px image + caption, zone title measured
// from its text. Used by the diagram-quality tests.
import type { LayoutInput } from "../../shared/layout";

const CHAR = 7.2;
const textWidth = (s: string) => Math.round(Math.max(...s.split("\n").map((l) => l.length)) * CHAR);

type NodeDef = [id: string, zone: string | null, label: string, size?: [number, number]];
type EdgeDef = [from: string, to: string, label?: string];
type ZoneDef = [id: string, title: string, parent?: string];

function fixture(zones: ZoneDef[], nodes: NodeDef[], edges: EdgeDef[], extra: Partial<LayoutInput> = {}): LayoutInput {
  return {
    direction: "right",
    spacing: 34,
    zones: zones.map(([id, title, parent]) => ({ id, parent, titleHeight: 31, minWidth: textWidth(title) + 44 })),
    nodes: nodes.map(([id, zone, label, size]) => ({
      id,
      zone: zone ?? undefined,
      // icon node: 52 px icon + caption; shapes carry their own size
      width: size ? size[0] : Math.max(60, textWidth(label) + 14),
      height: size ? size[1] : 84,
    })),
    edges: edges.map(([from, to, label], i) => ({
      id: `e${i + 1}`,
      from,
      to,
      label: label ? { width: textWidth(label) + 8, height: 21 } : undefined,
    })),
    ...extra,
  };
}

